package com.panish.ridebooking.driver.api;
import com.panish.ridebooking.driver.domain.Driver;import com.panish.ridebooking.driver.repository.DriverRepository;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/drivers") public class DriverController {private final DriverRepository repo;public DriverController(DriverRepository r){repo=r;}@PostMapping @ResponseStatus(HttpStatus.CREATED)public Driver create(@RequestBody CreateDriverRequest request){if(request.name()==null||request.name().isBlank())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"name is required");return repo.save(new Driver(request.name().trim()));}@GetMapping public List<Driver> all(){return repo.findAll();}@PatchMapping("/{id}/status")public Driver status(@PathVariable Long id,@RequestBody DriverStatusRequest request){Driver d=repo.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"Driver not found"));if(!List.of("AVAILABLE","BUSY").contains(request.status()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"status must be AVAILABLE or BUSY");d.setStatus(request.status());return repo.save(d);}public record CreateDriverRequest(String name){}public record DriverStatusRequest(String status){}}